-- Arbeitsrecht Berufsbildung > Soziale gesellschaftliche Themen > Nachhaltigkeit > Ressourcenschonung
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann Ressourcenschonung in einem IT-Betrieb durch energieeffiziente Hardware erreicht werden?', 2, '[{"text": "Ja", "correct": true, "because": "Energieeffiziente Hardware reduziert Stromverbrauch"}, {"text": "Nein", "correct": false, "because": "Effizienz ist eine Maßnahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein IT-Betrieb Ressourcenschonung gemäß gesetzlichen Vorschriften umsetzen?', 2, '[{"text": "Nein", "correct": true, "because": "Keine direkte gesetzliche Pflicht, aber freiwillige Standards existieren"}, {"text": "Ja", "correct": false, "because": "Nachhaltigkeit ist oft freiwillig"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Fachinformatiker durch Recycling von Hardware zur Ressourcenschonung beitragen?', 2, '[{"text": "Ja", "correct": true, "because": "Recycling reduziert Abfall und Ressourcenverbrauch"}, {"text": "Nein", "correct": false, "because": "Recycling ist effektiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Ressourcenschonung in einem IT-Betrieb nur für Energie relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Materialien und Wasser sind betroffen"}, {"text": "Ja", "correct": false, "because": "Umfassender Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Ressourcenschonung die Betriebskosten eines IT-Betriebs senken?', 2, '[{"text": "Ja", "correct": true, "because": "Effizienz spart Energie und Materialkosten"}, {"text": "Nein", "correct": false, "because": "Kostensenkung ist möglich"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme fördert die Ressourcenschonung in einem IT-Betrieb?', 2, '[{"text": "Energieeffiziente Server", "correct": true, "because": "Reduziert Stromverbrauch"}, {"text": "Einweg-Hardware", "correct": false, "because": "Erhöht Abfall"}, {"text": "Hoher Papierverbrauch", "correct": false, "because": "Nicht ressourcenschonend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptziel der Ressourcenschonung in einem IT-Betrieb?', 3, '[{"text": "Reduzierung des ökologischen Fußabdrucks", "correct": true, "because": "Nachhaltigkeit zielt auf Umweltschutz"}, {"text": "Erhöhung der Arbeitszeit", "correct": false, "because": "Kein Ziel"}, {"text": "Steigerung der Kosten", "correct": false, "because": "Nicht beabsichtigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ressource wird durch Recycling von Hardware in einem IT-Betrieb geschont?', 3, '[{"text": "Metalle und Kunststoffe", "correct": true, "because": "Hardware enthält wertvolle Materialien"}, {"text": "Arbeitszeit", "correct": false, "because": "Keine Ressource"}, {"text": "Kundenzufriedenheit", "correct": false, "because": "Kein direkter Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer ist in einem IT-Betrieb typischerweise für die Umsetzung von Ressourcenschonung verantwortlich?', 2, '[{"text": "Das Management", "correct": true, "because": "Management legt Strategien fest"}, {"text": "Die Auszubildenden", "correct": false, "because": "Nicht primär deren Aufgabe"}, {"text": "Die Kunden", "correct": false, "because": "Kunden haben keinen Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Vorteil ergibt sich durch Ressourcenschonung für einen IT-Betrieb?', 3, '[{"text": "Kosteneinsparung", "correct": true, "because": "Effizienz senkt Betriebskosten"}, {"text": "Höhere Arbeitsbelastung", "correct": false, "because": "Kein Vorteil"}, {"text": "Weniger Produktivität", "correct": false, "because": "Produktivität bleibt oder steigt"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen fördern die Ressourcenschonung in einem IT-Betrieb?', 4, '[{"text": "Energieeffiziente Hardware", "correct": true, "because": "Reduziert Stromverbrauch"}, {"text": "Recycling von Altgeräten", "correct": true, "because": "Schont Materialien"}, {"text": "Hoher Papierverbrauch", "correct": false, "because": "Nicht ressourcenschonend"}, {"text": "Cloud Computing", "correct": true, "because": "Kann Energieverbrauch zentralisieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Ressourcenschonung einem IT-Betrieb?', 3, '[{"text": "Kostensenkung", "correct": true, "because": "Effizienz spart Geld"}, {"text": "Verbessertes Image", "correct": true, "because": "Nachhaltigkeit stärkt Reputation"}, {"text": "Höhere Arbeitsbelastung", "correct": false, "because": "Kein Vorteil"}, {"text": "Umweltschutz", "correct": true, "because": "Reduziert ökologischen Fußabdruck"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ressourcen können in einem IT-Betrieb geschont werden?', 4, '[{"text": "Energie", "correct": true, "because": "Durch effiziente Geräte"}, {"text": "Metalle", "correct": true, "because": "Durch Recycling"}, {"text": "Kundendaten", "correct": false, "because": "Keine Ressource"}, {"text": "Papier", "correct": true, "because": "Durch Digitalisierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile kann Ressourcenschonung für einen IT-Betrieb haben?', 3, '[{"text": "Kurzfristige Investitionskosten", "correct": true, "because": "Effiziente Geräte kosten initial"}, {"text": "Komplexere Prozesse", "correct": true, "because": "Recycling erfordert Planung"}, {"text": "Weniger Produktivität", "correct": false, "because": "Produktivität bleibt oder steigt"}, {"text": "Zeitaufwand für Umsetzung", "correct": true, "because": "Maßnahmen brauchen Zeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Praktiken unterstützen die Ressourcenschonung in einem IT-Betrieb?', 3, '[{"text": "Digitalisierung statt Papier", "correct": true, "because": "Reduziert Papierverbrauch"}, {"text": "Wiederverwendung von Hardware", "correct": true, "because": "Schont Materialien"}, {"text": "Hoher Energieverbrauch", "correct": false, "because": "Nicht ressourcenschonend"}, {"text": "Energieeffiziente Software", "correct": true, "because": "Senkt Strombedarf"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ressourcenschonung kann den Stromverbrauch in einem IT-Betrieb senken. b) Ressourcenschonung ist gesetzlich vorgeschrieben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Stromverbrauch ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Recycling von Hardware fördert die Ressourcenschonung in einem IT-Betrieb. b) Ressourcenschonung kann die Betriebskosten senken.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Recycling und Kostensenkung"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ressourcenschonung schützt die Umwelt in einem IT-Betrieb. b) Ressourcenschonung erhöht kurzfristig die Kosten.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Umweltschutz und Kosten"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Energieeffiziente Server fördern die Ressourcenschonung in einem IT-Betrieb. b) Ressourcenschonung ist nur für Energie relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Server ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ressourcenschonung kann das Image eines IT-Betriebs verbessern. b) Das Management ist für die Umsetzung verantwortlich.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Image und Verantwortung"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]');

